#!/usr/bin/env python3
"""Exercise the actual ASGI endpoint on loopback using only generated bytes."""
import argparse
import asyncio
import datetime
import hashlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from pathlib import Path
import socket
import subprocess
import sys
import tempfile
import threading
import time
import urllib.error
import urllib.parse
import urllib.request


PAYLOAD = bytes(range(256)) * 1024
PREFIX = b'\x89PNG\r\n\x1a\n'


class Upstream(BaseHTTPRequestHandler):
    def log_message(self, *args):
        pass

    def do_GET(self):
        data = PREFIX + PAYLOAD
        header = self.headers.get('Range', '')
        start, end = 0, len(data)-1
        code = 200
        if header and self.path != '/d/ignore':
            left, right = header[6:].split('-')
            if not left:
                start = max(0, len(data) - int(right))
            else:
                start = int(left)
                end = min(int(right), end) if right else end
            if start >= len(data):
                self.send_response(416)
                self.send_header('Content-Range', 'bytes */'+str(len(data)))
                self.end_headers()
                return
            code = 206
        self.send_response(code)
        self.send_header('Content-Type','application/octet-stream')
        self.send_header('Content-Length',str(end-start+1))
        if code == 206:
            self.send_header('Content-Range',f'bytes {start}-{end}/{len(data)}')
        self.end_headers()
        try:
            self.wfile.write(data[start:end+1])
        except (BrokenPipeError, ConnectionResetError):
            pass


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--output', required=True)
    args = ap.parse_args()
    upstream = ThreadingHTTPServer(('127.0.0.1',0),Upstream)
    thread = threading.Thread(target=upstream.serve_forever,daemon=True)
    thread.start()
    with tempfile.TemporaryDirectory(prefix='vod-http-') as tmp:
        sock = socket.socket()
        sock.bind(('127.0.0.1',0))
        port = sock.getsockname()[1]
        env = dict(os.environ, VOD_BASE_DIR=tmp, VOD_DATA_DIR=tmp+'/data',
                   VOD_STATE_DB=tmp+'/data/quark_plays.db',
                   QUARK_COOKIE_OVERRIDE_FILE=tmp+'/data/quark_cookie.txt',
                   VOD_CINEMA2_DIR=tmp+'/cinema2', VOD_LOG_DIR=tmp+'/logs',
                   VOD_LOG_FILE=tmp+'/logs/verify.log', VOD_ENV_FILE='',
                   OPENLIST_PUBLIC=f'http://127.0.0.1:{upstream.server_port}',
                   OPENLIST_API=f'http://127.0.0.1:{upstream.server_port}',
                   AI_PARSE_ENABLED='0', SELFHEAL_ENABLED='0',
                   VOD_JELLYFIN_ENABLED='0', VOD_MAINTENANCE_ENABLED='0',
                   VOD_STARTUP_SCAN='0', VOD_STARTUP_WRITE_PROBE='0')
        project = Path(__file__).resolve().parents[1]
        proc = subprocess.Popen([sys.executable,'-m','uvicorn','main:app','--fd',str(sock.fileno()),'--lifespan','off','--no-access-log'],
                                cwd=project/'app',env=env,pass_fds=(sock.fileno(),),stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
        cases=[]
        try:
            for _ in range(50):
                try:
                    with urllib.request.urlopen(f'http://127.0.0.1:{port}/health',timeout=1):break
                except OSError:
                    if proc.poll() is not None:raise RuntimeError('isolated ASGI exited')
                    time.sleep(.1)
            for endpoint in ('/d/range','/d/ignore'):
                for rng,start,end in [('',0,len(PAYLOAD)),('bytes=0-0',0,1),('bytes=123-456',123,457),('bytes=123-',123,len(PAYLOAD)),('bytes=-333',len(PAYLOAD)-333,len(PAYLOAD)),('bytes=-999999',0,len(PAYLOAD)),('bytes=0-1,4-5',0,len(PAYLOAD))]:
                    raw=f'http://127.0.0.1:{upstream.server_port}'+endpoint
                    url=f'http://127.0.0.1:{port}/clean?'+urllib.parse.urlencode({'url':raw,'skip':8})
                    headers={'Range':rng} if rng else {}
                    for method in ('GET','HEAD'):
                        with urllib.request.urlopen(urllib.request.Request(url,headers=headers,method=method),timeout=5) as response:
                            body=response.read()
                            expected=PAYLOAD[start:end] if method=='GET' else b''
                            expected_status=206 if rng and ',' not in rng else 200
                            assert body==expected and response.status==expected_status
                            assert int(response.headers['Content-Length'])==end-start
                            cases.append({'upstream':endpoint,'range':rng,'method':method,'pass':True})
            report={'time':datetime.datetime.now().astimezone().isoformat(),'cases':cases,'all_passed':True}
            Path(args.output).write_text(json.dumps(report,indent=2)+'\n')
            print('PASS',len(cases),'real HTTP range/body/HEAD cases')
        finally:
            proc.terminate()
            try:proc.wait(timeout=5)
            except subprocess.TimeoutExpired:proc.kill();proc.wait(timeout=5)
            sock.close()
            upstream.shutdown()
            upstream.server_close()


if __name__=='__main__':
    main()
